package com.jarvis.assistant.voice

import com.jarvis.assistant.core.AppLanguage
import com.jarvis.assistant.core.choose

/** ProviderException messages are generated by BrainProtocol, never raw provider payloads. */
object BackendVoiceErrors {
    fun message(error:Exception,language:AppLanguage):String?=when(error){
        is com.jarvis.assistant.data.ProviderException->error.message?.take(600)
        is com.jarvis.assistant.local.LocalModelUnavailable->language.choose("The configured local AI model is unavailable. Time, date, battery and app commands still work. Open Neural Core to configure or download the model.","El modelo de IA local no está disponible. Hora, fecha, batería y aplicaciones siguen funcionando. Abre Núcleo Neural para configurarlo.","مدل محلی هوش مصنوعی در دسترس نیست.")
        is java.net.SocketTimeoutException->language.choose("The configured AI backend connection timed out. Please check its connection and try again.","La conexión con la IA agotó el tiempo. Revisa la conexión e inténtalo de nuevo.","زمان اتصال به هوش مصنوعی پایان یافت.")
        is java.net.UnknownHostException->language.choose("The configured AI server could not be resolved. Check internet and the backend settings.","No se pudo resolver el servidor de IA. Revisa internet y sus ajustes.","نشانی سرور هوش مصنوعی پیدا نشد.")
        is java.net.ConnectException->language.choose("The configured AI backend could not be reached. Check the server and connection settings.","No se pudo acceder al servidor de IA. Revisa el servidor y la conexión.","اتصال به سرور هوش مصنوعی برقرار نشد.")
        is javax.net.ssl.SSLException->language.choose("The secure connection to the configured AI backend failed. Check its TLS certificate and connection settings.","Falló la conexión segura con la IA. Revisa su certificado TLS y la conexión.","اتصال امن هوش مصنوعی برقرار نشد.")
        is java.io.IOException->language.choose("The configured AI connection failed while receiving the response. Please check the connection and try again.","La conexión con la IA falló al recibir la respuesta. Revisa la conexión e inténtalo de nuevo.","دریافت پاسخ هوش مصنوعی ناموفق بود.")
        else->null
    }
}
